<?php
require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_hrd']);$page_title='Dokumen Pendukung HRD';
$storage=__DIR__.'/storage/hrd_documents';if(!is_dir($storage))mkdir($storage,0750,true);if(!file_exists($storage.'/.htaccess'))file_put_contents($storage.'/.htaccess',"Require all denied\nDeny from all\n");
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$person=(int)($_POST['personnel_id']??0);$type=trim($_POST['document_type']??'');$file=$_FILES['document']??null;$q=$pdo->prepare('SELECT id FROM hrd_personnel WHERE id=?');$q->execute([$person]);if(!$q->fetchColumn()||!$type||!$file||$file['error']!==UPLOAD_ERR_OK){flash('Pilih personel, jenis dokumen, dan file yang valid.');header('Location: hrd_documents.php');exit;}$allowed=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($allowed[$ext])||$mime!==$allowed[$ext]||$file['size']>10*1024*1024){flash('Format yang diizinkan: PDF, JPG, PNG, DOC, DOCX; maksimal 10 MB.');header('Location: hrd_documents.php');exit;}$stored=bin2hex(random_bytes(18)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$storage.'/'.$stored)){flash('File gagal disimpan.');header('Location: hrd_documents.php');exit;}$q=$pdo->prepare('INSERT INTO hrd_documents(personnel_id,document_type,file_name,original_name,uploaded_by) VALUES(?,?,?,?,?)');$q->execute([$person,$type,$stored,basename($file['name']),$_SESSION['user']['id']]);flash('Dokumen berhasil diunggah.');header('Location: hrd_documents.php?personnel_id='.$person);exit;}
$people=$pdo->query('SELECT id,name FROM hrd_personnel ORDER BY name')->fetchAll();$selected=(int)($_GET['personnel_id']??0);$sql='SELECT d.*,p.name personnel_name FROM hrd_documents d JOIN hrd_personnel p ON p.id=d.personnel_id';$params=[];if($selected){$sql.=' WHERE d.personnel_id=?';$params[]=$selected;}$sql.=' ORDER BY d.uploaded_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();require __DIR__.'/includes/header.php';show_flash();
?>
<section class="panel"><div class="panel-head"><h3>Unggah Dokumen Pendukung</h3></div><p>Format: PDF, JPG, PNG, DOC, DOCX. Maksimal 10 MB per file. Dokumen disimpan di folder yang tidak dapat diakses langsung dari URL.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Personel</label><select name="personnel_id" required><option value="">Pilih personel</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=$selected===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Jenis dokumen</label><input name="document_type" required placeholder="KTP, CV, ijazah, kontrak..."></div><div class="field full"><label>Pilih file</label><input type="file" name="document" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" required></div></div><div class="form-actions"><button class="btn">Unggah Dokumen</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Arsip Dokumen</h3></div><table><thead><tr><th>Personel</th><th>Jenis</th><th>Nama file</th><th>Tanggal unggah</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">Belum ada dokumen.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['personnel_name'])?></td><td><?=e($r['document_type'])?></td><td><?=e($r['original_name'])?></td><td><?=e($r['uploaded_at'])?></td><td><a class="btn btn-light" href="download_hrd_document.php?id=<?=$r['id']?>">Unduh</a></td></tr><?php endforeach;endif;?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php';?>
